entries[197393] = { ["name"] = "Abschluss: Ausweiden", ["text"] = "35 Energie / 1 zu 5 Combopunkte Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der das Ziel ausweidet und mehr Schaden pro Combopunkt verursacht:\n1 Punkt: [((1 + Vielseitigkeit)) * (31.5% der Angriffskraft)] Schaden\n2 Punkte: [((1 + Vielseitigkeit)) * (31.5% der Angriffskraft) * 2] Schaden\n3 Punkte: [((1 + Vielseitigkeit)) * (31.5% der Angriffskraft) * 3] Schaden\n4 Punkte: [((1 + Vielseitigkeit)) * (31.5% der Angriffskraft) * 4] Schaden\n5 Punkte: [((1 + Vielseitigkeit)) * (31.5% der Angriffskraft) * 5] Schaden [ Meisterlicher Stratege : 6 Punkte: [((1 + Vielseitigkeit)) * (31.5% der Angriffskraft) * 6] Schaden ]" }
